SELECT clubowner_key FROM clubOwner WHERE memberIdx = #{memberIdx}
UNION
SELECT p.clubowner_key FROM Player p JOIN clubJoin cj ON p.clubJoin_num = cj.clubJoin_num JOIN Club c ON c.clubOwner_key = p.clubowner_key WHERE cj.memberIdx = #{memberIdx} AND c.club_status = '1' FETCH FIRST 1 ROWS ONLY
